// Renders the GdI course timeline ("Zeitplan") and the lesson table ("Lehrplan") from the
// DATA block `timeline`, which holds the out.json generated by gdi/source/buildTimeline.js.
// `previews` maps a lecture number to its base64 preview image and `recordings` lists the
// recording url per lecture (null until known); both are generated by `buildTimeline.js -d`.
// `links` lists the quick links shown below the header (title, href, target, description,
// color, icon, disabled; color is yellow/purple/blue/coral/green or any css color,
// icon a key of SVG). A link with `disabled: true` is not shown.
// Nothing is loaded from outside, except the live slide previews (liveEmbed) in an iframe.
// No program is run; everything is built when the playground is initialized.
// This is the v101 (script version 2.0) variant of timelinePlayground.js: a plain object
// literal, so the helpers are methods of the object.
{
    view: 'timeline',
    selected: 0, 
    today: 0,

    MAX_CONTENT_PER_DAY: 4,

    // the timeline data uses Material Design Icons, we show the matching lucide icons instead
    ICONS: {
        'mdi-cast-education': 'cast',
        'mdi-school': 'graduation-cap',
        'mdi-account-check': 'user-check',
        'mdi-alarm-check': 'alarm-clock-check',
        'mdi-alarm-off': 'alarm-clock-off',
        'mdi-alert-octagram': 'octagon-alert',
        'mdi-video-wireless': 'radio-tower',
        'mdi-file-video': 'file-video-camera',
        'mdi-clipboard-text': 'clipboard-pen-line',
    },

    // lucide icons (ISC license, https://lucide.dev) as inline svg markup, <cb-icon> does not
    // exist in v101. Add the inner markup of any other lucide icon here to use it in `links`.
    SVG: {
        'cast': '<path d="M2 8V6a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-6"/><path d="M2 12a9 9 0 0 1 8 8"/><path d="M2 16a5 5 0 0 1 4 4"/><line x1="2" x2="2.01" y1="20" y2="20"/>',
        'graduation-cap': '<path d="M21.42 10.922a1 1 0 0 0-.019-1.838L12.83 5.18a2 2 0 0 0-1.66 0L2.6 9.08a1 1 0 0 0 0 1.832l8.57 3.908a2 2 0 0 0 1.66 0z"/><path d="M22 10v6"/><path d="M6 12.5V16a6 3 0 0 0 12 0v-3.5"/>',
        'user-check': '<path d="m16 11 2 2 4-4"/><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/>',
        'alarm-clock-check': '<circle cx="12" cy="13" r="8"/><path d="M5 3 2 6"/><path d="m22 6-3-3"/><path d="M6.38 18.7 4 21"/><path d="M17.64 18.67 20 21"/><path d="m9 13 2 2 4-4"/>',
        'alarm-clock-off': '<path d="M6.87 6.87a8 8 0 1 0 11.26 11.26"/><path d="M19.9 14.25a8 8 0 0 0-9.15-9.15"/><path d="m22 6-3-3"/><path d="M6.26 18.67 4 21"/><path d="m2 2 20 20"/><path d="M4 4 2 6"/>',
        'octagon-alert': '<path d="M12 16h.01"/><path d="M12 8v4"/><path d="M15.312 2a2 2 0 0 1 1.414.586l4.688 4.688A2 2 0 0 1 22 8.688v6.624a2 2 0 0 1-.586 1.414l-4.688 4.688a2 2 0 0 1-1.414.586H8.688a2 2 0 0 1-1.414-.586l-4.688-4.688A2 2 0 0 1 2 15.312V8.688a2 2 0 0 1 .586-1.414l4.688-4.688A2 2 0 0 1 8.688 2z"/>',
        'radio-tower': '<path d="M4.9 16.1C1 12.2 1 5.8 4.9 1.9"/><path d="M7.8 4.7a6.14 6.14 0 0 0-.8 7.5"/><circle cx="12" cy="9" r="2"/><path d="M16.2 4.8c2 2 2.26 5.11.8 7.47"/><path d="M19.1 1.9a9.96 9.96 0 0 1 0 14.1"/><path d="M9.5 18h5"/><path d="m8 22 4-11 4 11"/>',
        'file-video-camera': '<path d="M4 12V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.706.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2"/><path d="M14 2v5a1 1 0 0 0 1 1h5"/><path d="m10 17.843 3.033-1.755a.64.64 0 0 1 .967.56v4.704a.65.65 0 0 1-.967.56L10 20.157"/><rect width="7" height="6" x="3" y="16" rx="1"/>',
        'clipboard-pen-line': '<rect width="8" height="4" x="8" y="2" rx="1"/><path d="M8 4H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-.5"/><path d="M16 4h2a2 2 0 0 1 1.73 1"/><path d="M8 18h1"/><path d="M21.378 12.626a1 1 0 0 0-3.004-3.004l-4.01 4.012a2 2 0 0 0-.506.854l-.837 2.87a.5.5 0 0 0 .62.62l2.87-.837a2 2 0 0 0 .854-.506z"/>',
        'calendar-off': '<path d="M4.2 4.2A2 2 0 0 0 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 1.82-1.18"/><path d="M21 15.5V6a2 2 0 0 0-2-2H9.5"/><path d="M16 2v4"/><path d="M3 10h7"/><path d="M21 10h-5.5"/><path d="m2 2 20 20"/>',
        'calendar': '<path d="M8 2v4"/><path d="M16 2v4"/><rect width="18" height="18" x="3" y="4" rx="2"/><path d="M3 10h18"/>',
        'presentation': '<path d="M2 3h20"/><path d="M21 3v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V3"/><path d="m7 21 5-5 5 5"/>',
        'circle-play': '<path d="M9 9.003a1 1 0 0 1 1.517-.859l4.997 2.997a1 1 0 0 1 0 1.718l-4.997 2.997A1 1 0 0 1 9 14.996z"/><circle cx="12" cy="12" r="10"/>',
        'file-text': '<path d="M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z"/><path d="M14 2v5a1 1 0 0 0 1 1h5"/><path d="M10 9H8"/><path d="M16 13H8"/><path d="M16 17H8"/>',
        'award': '<path d="m15.477 12.89 1.515 8.526a.5.5 0 0 1-.81.47l-3.58-2.687a1 1 0 0 0-1.197 0l-3.586 2.686a.5.5 0 0 1-.81-.469l1.514-8.526"/><circle cx="12" cy="8" r="6"/>',
        'calendar-range': '<rect width="18" height="18" x="3" y="4" rx="2"/><path d="M16 2v4"/><path d="M3 10h18"/><path d="M8 2v4"/><path d="M17 14h-6"/><path d="M13 18H7"/><path d="M7 14h.01"/><path d="M17 18h.01"/>',
        'table-2': '<path d="M9 3H5a2 2 0 0 0-2 2v4m6-6h10a2 2 0 0 1 2 2v4M9 3v18m0 0h10a2 2 0 0 0 2-2V9M9 21H5a2 2 0 0 1-2-2V9m0 0h18"/>',
        'chevron-left': '<path d="m15 18-6-6 6-6"/>',
        'chevron-right': '<path d="m9 18 6-6-6-6"/>',
        'book-open': '<path d="M12 7v14"/><path d="M3 18a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h5a4 4 0 0 1 4 4 4 4 0 0 1 4-4h5a1 1 0 0 1 1 1v13a1 1 0 0 1-1 1h-6a3 3 0 0 0-3 3 3 3 0 0 0-3-3z"/>',
        'list-checks': '<path d="M13 5h8"/><path d="M13 12h8"/><path d="M13 19h8"/><path d="m3 17 2 2 4-4"/><path d="m3 7 2 2 4-4"/>',
        'square-code': '<path d="m10 9-3 3 3 3"/><path d="m14 15 3-3-3-3"/><rect x="3" y="3" width="18" height="18" rx="2"/>',
        'messages-square': '<path d="M16 10a2 2 0 0 1-2 2H6.828a2 2 0 0 0-1.414.586l-2.202 2.202A.71.71 0 0 1 2 14.286V4a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/><path d="M20 9a2 2 0 0 1 2 2v10.286a.71.71 0 0 1-1.212.502l-2.202-2.202A2 2 0 0 0 17.172 19H10a2 2 0 0 1-2-2v-1"/>',
        'radio': '<path d="M16.247 7.761a6 6 0 0 1 0 8.478"/><path d="M19.075 4.933a10 10 0 0 1 0 14.134"/><path d="M4.925 19.067a10 10 0 0 1 0-14.134"/><path d="M7.753 16.239a6 6 0 0 1 0-8.478"/><circle cx="12" cy="12" r="2"/>',
        'layout-grid': '<rect width="7" height="7" x="3" y="3" rx="1"/><rect width="7" height="7" x="14" y="3" rx="1"/><rect width="7" height="7" x="14" y="14" rx="1"/><rect width="7" height="7" x="3" y="14" rx="1"/>',
        'external-link': '<path d="M15 3h6v6"/><path d="M10 14 21 3"/><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6"/>',
        // own icon in lucide style: the outline of lucide's map with a trail to an X (Lernwerk)
        'treasure-map': '<path d="M14.106 5.553a2 2 0 0 0 1.788 0l3.659-1.83A1 1 0 0 1 21 4.619v12.764a1 1 0 0 1-.553.894l-4.553 2.277a2 2 0 0 1-1.788 0l-4.212-2.106a2 2 0 0 0-1.788 0l-3.659 1.83A1 1 0 0 1 3 19.381V6.618a1 1 0 0 1 .553-.894l4.553-2.277a2 2 0 0 1 1.788 0z"/><path d="M7 16h.01M9.5 14.5h.01M11.5 12.5h.01"/><path d="M14 8l3 3M17 8l-3 3"/>',
    },

    MONTHS: [
        'Januar',
        'Februar',
        'März',
        'April',
        'Mai',
        'Juni',
        'Juli',
        'August',
        'September',
        'Oktober',
        'November',
        'Dezember',
    ],
    WEEKDAYS: ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'],

    holidayCache: {},

    init(canvasElement, outputElement, scope, runner) {
        // work on a copy, the DATA blocks are shared with the editor
        this.weeks = JSON.parse(JSON.stringify(this.DATA['timeline'] ?? []))
        this.previews = this.DATA['previews'] ?? {}
        // a link with `disabled: true` is prepared for later and not shown yet
        this.links = (Array.isArray(this.DATA['links']) ? this.DATA['links'] : []).filter(
            (l) => !l.disabled
        )
        canvasElement.empty()
        // v101 draws a dashed frame around the canvas (.playground in PlaygroundCanvas.vue)
        canvasElement.css('border', 'none')
        if (!Array.isArray(this.weeks) || this.weeks.length === 0) {
            canvasElement.html(
                '<p style="padding:16px">Der DATA-Block <b>timeline</b> enthält keine Wochen.</p>'
            )
            return
        }
        this.applyRecordings(this.weeks, this.DATA['recordings'])
        this.sem = this.semesterOf(this.weeks)

        this.root = $(`<div class="gdi-tl">
            <style>${this.css()}</style>
            <div class="tl-hero ${this.links.length ? 'has-links' : ''}">
                <div class="tl-hero-top">
                    <div>
                        <div class="tl-hero-kicker">${this.semesterName()}</div>
                        <h1>Grundlagen der Informatik</h1>
                    </div>
                    <div class="tl-tabs" role="tablist">
                        <button type="button" role="tab" data-view="timeline">${this.icon('calendar-range')} Zeitplan</button>
                        <button type="button" role="tab" data-view="table">${this.icon('table-2')} Lehrplan</button>
                    </div>
                </div>
                ${this.progressBar()}
            </div>
            ${this.linkBar()}
            <div class="tl-body"></div>
        </div>`)
        canvasElement.append(this.root)

        const now = new Date()
        this.selected = this.weekIndexFor(now)
        this.today = this.selected
        this.root.on('click', '[data-view]', (e) =>
            this.show($(e.currentTarget).attr('data-view'))
        )
        this.root.on('click', '[data-week]', (e) =>
            this.selectWeek(+$(e.currentTarget).attr('data-week'))
        )
        this.root.on('keydown', '.tl-week-nav', (e) => {
            if (e.key === 'ArrowLeft') this.selectWeek(this.selected - 1)
            if (e.key === 'ArrowRight') this.selectWeek(this.selected + 1)
        })
        this.show(this.view)
    },

    update(txt, json, canvasElement, outputElement) {
        return txt
    },

    reset(canvasElement) {},

    // ---------- icons & markup ----------
    icon(name) {
        return `<svg class="tl-icon" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${this.SVG[name] ?? ''}</svg>`
    },
    mdiIcon(cls) {
        return this.icon(this.ICONS[cls] ?? 'calendar')
    },
    // <span class="mdi mdi-…"></span> in the title/content markup
    markup(html) {
        return (html ?? '').replace(
            /<span class="mdi (mdi-[a-z-]+)"><\/span>/g,
            (_, cls) => `<span class="tl-inline-icon">${this.mdiIcon(cls)}</span>`
        )
    },

    // same as applyRecordings in gdi/resources/timeline.js: a lecture with a recording links
    // to the recording instead of the livestream
    applyRecordings(weeks, recordings) {
        if (!Array.isArray(recordings)) return
        for (const e of weeks.flatMap((w) => w.events ?? [])) {
            if (e.type !== 'lecture') continue
            const rec = recordings.find((r) => r.nr === e.nr)
            if (!rec || !rec.url) continue
            const link = `<a href="${rec.url}" target="_blank" class="recording"><span class="mdi mdi-file-video"></span></a>`
            e.title = e.title.replace(/<a [^>]*class="stream lecture"[^>]*>.*?<\/a>/, link)
        }
    },

    // ---------- dates (local time, day precision) ----------
    parseDay(iso) {
        const [y, m, d] = iso.split('-').map(Number)
        return new Date(y, m - 1, d)
    },
    addDays(date, n) {
        return new Date(date.getFullYear(), date.getMonth(), date.getDate() + n)
    },
    sameDay(a, b) {
        return (
            a.getFullYear() === b.getFullYear() &&
            a.getMonth() === b.getMonth() &&
            a.getDate() === b.getDate()
        )
    },
    dayDiff(a, b) {
        return Math.round(
            (this.parseDay(this.isoDay(b)) - this.parseDay(this.isoDay(a))) / 86400000
        )
    },
    isoDay(date) {
        return `${date.getFullYear()}-${this.pad(date.getMonth() + 1)}-${this.pad(date.getDate())}`
    },
    pad(n) {
        return String(n).padStart(2, '0')
    },
    isoWeekday(date) {
        return (date.getDay() + 6) % 7 // 0 = Monday
    },
    fmtDay(date) {
        return `${date.getDate()}. ${this.MONTHS[date.getMonth()]}`
    },
    fmtShort(date) {
        return `${this.pad(date.getDate())}.${this.pad(date.getMonth() + 1)}.${String(date.getFullYear()).slice(2)}`
    },
    monthShort(date) {
        return this.MONTHS[date.getMonth()].slice(0, 3)
    },

    // the vacation days of a week (from settings.vacation in buildTimeline.js) as ranges of
    // consecutive days, ranges that only cover a weekend are left out
    vacationRanges(week) {
        const ranges = []
        for (const day of [...(week.vacations ?? [])].sort().map((d) => this.parseDay(d))) {
            const last = ranges.at(-1)
            if (last && this.dayDiff(last.end, day) === 1) last.end = day
            else ranges.push({ start: day, end: day })
        }
        return ranges.filter((r) => {
            for (let d = r.start; d <= r.end; d = this.addDays(d, 1))
                if (this.isoWeekday(d) < 5) return true
            return false
        })
    },

    isoWeek(date) {
        const thursday = this.addDays(date, 3 - this.isoWeekday(date))
        const firstThursday = new Date(thursday.getFullYear(), 0, 4)
        return (
            1 +
            Math.round(
                (this.dayDiff(firstThursday, thursday) - 3 + this.isoWeekday(firstThursday)) / 7
            )
        )
    },

    easterSunday(year) {
        const a = year % 19,
            b = Math.floor(year / 100),
            c = year % 100
        const d = Math.floor(b / 4),
            e = b % 4,
            f = Math.floor((b + 8) / 25)
        const g = Math.floor((b - f + 1) / 3),
            h = (19 * a + b - d - g + 15) % 30
        const i = Math.floor(c / 4),
            k = c % 4,
            l = (32 + 2 * e + 2 * i - h - k) % 7
        const m = Math.floor((a + 11 * h + 22 * l) / 451)
        const month = Math.floor((h + l - 7 * m + 114) / 31)
        return new Date(year, month - 1, ((h + l - 7 * m + 114) % 31) + 1)
    },

    // public holidays in Bavaria
    isHoliday(date) {
        const year = date.getFullYear()
        if (!this.holidayCache[year]) {
            const easter = this.easterSunday(year)
            const fixed = [
                '01-01',
                '01-06',
                '05-01',
                '08-15',
                '10-03',
                '11-01',
                '12-25',
                '12-26',
            ].map((md) => `${year}-${md}`)
            const moving = [-2, 1, 39, 50, 60].map((n) => this.isoDay(this.addDays(easter, n)))
            this.holidayCache[year] = new Set(fixed.concat(moving))
        }
        return this.holidayCache[year].has(this.isoDay(date))
    },

    // "w26" for a winter term starting in October 2026, "s27" for a summer term
    semesterOf(weeks) {
        const start = this.parseDay(weeks[0].start)
        return (start.getMonth() >= 8 ? 'w' : 's') + String(start.getFullYear()).slice(2)
    },

    minutesOf(time) {
        const [h, m] = (time ?? '').replace('ab', '').trim().split(':').map(Number)
        return isNaN(h) ? undefined : h * 60 + (m || 0)
    },

    // ---------- link helpers ----------
    videoHref(lecture) {
        if (!lecture.videoTime) return lecture.video
        const parts = lecture.videoTime.split(':').map(Number)
        const [min, sec] = parts.length > 2 ? [parts[0] * 60 + parts[1], parts[2]] : parts
        return `${lecture.video}#offset=${min}m${sec}s`
    },

    actionLink(href, iconName, label, cls = '') {
        if (!href) return ''
        return `<a class="tl-action ${cls}" href="${href}" target="_blank" rel="noopener" title="${label}" aria-label="${label}">${this.icon(iconName)}</a>`
    },

    lectureActions(lecture) {
        return [
            this.actionLink(lecture.slides, 'presentation', 'Interaktive Folien'),
            this.actionLink(
                lecture.video && this.videoHref(lecture),
                'circle-play',
                lecture.videoTime
                    ? `Videoaufzeichnung ab ${lecture.videoTime}`
                    : 'Videoaufzeichnung'
            ),
            this.actionLink(lecture.pdf, 'file-text', 'Druckbares PDF'),
            this.actionLink(lecture.test, 'award', 'Vorlesungstest', 'accent'),
        ].join('')
    },

    semesterName() {
        const year = 2000 + +this.sem.slice(1)
        return this.sem.startsWith('w')
            ? `Wintersemester ${year}/${String(year + 1).slice(2)}`
            : `Sommersemester ${year}`
    },

    // how far the semester has progressed (from the first to the last week)
    progressBar() {
        const first = this.parseDay(this.weeks[0].start)
        const last = this.addDays(this.parseDay(this.weeks[this.weeks.length - 1].end), 1)
        const now = new Date()
        const ratio = Math.min(1, Math.max(0, (now - first) / (last - first)))
        let text = `Woche ${this.weeks[this.weekIndexFor(now)].week} von ${this.weeks.length}`
        if (now < first)
            text = `Start in ${this.dayDiff(now, first)} Tagen · ${this.fmtDay(first)}`
        if (now >= last) text = 'Vorlesungszeit beendet'
        return `<div class="tl-progress">
                <div class="tl-progress-track"><div class="tl-progress-fill" style="width:${(ratio * 100).toFixed(1)}%"></div></div>
                <span>${text}</span>
            </div>`
    },

    // ---------- quick links ----------
    // a row of slightly crooked stickers, every one tilted and shifted a bit differently
    linkBar() {
        if (this.links.length === 0) return ''
        return `<nav class="tl-links" aria-label="Links">${this.links.map((l, i) => this.linkSticker(l, i)).join('')}</nav>`
    },

    linkSticker(link, i) {
        const TILT = [-2.5, 1.8, -1.2, 3, -3.2, 1.2, -0.6, 2.4]
        const SHIFT = [4, -5, 7, -2, 6, -7, 1, 5]
        const NAMED = ['yellow', 'purple', 'blue', 'coral', 'green']
        const color = link.color ?? NAMED[i % NAMED.length]
        const named = NAMED.includes(color)
        const style = `--tilt:${TILT[i % TILT.length]}deg;--shift:${SHIFT[i % SHIFT.length]}px${named ? '' : `;--bg:${color}`}`
        const target = link.target ?? '_blank'
        return `<a class="tl-link ${named ? 'c-' + color : ''}" href="${link.href ?? '#'}" target="${target}" rel="noopener" style="${style}">
                <span class="tl-link-title">${link.icon ? this.icon(link.icon) : ''}${link.title ?? ''}</span>
                ${link.description ? `<span class="tl-link-desc">${link.description}</span>` : ''}
            </a>`
    },

    // the current week; before the term the first, afterwards the last one
    weekIndexFor(date) {
        let idx = 0
        this.weeks.forEach((w, i) => {
            if (this.parseDay(w.start) <= date) idx = i
        })
        return idx
    },

    show(view) {
        this.view = view
        this.root.find('[data-view]').each((_, el) => {
            const active = $(el).attr('data-view') === view
            $(el).toggleClass('active', active).attr('aria-selected', active)
        })
        const body = this.root.find('.tl-body')
        body.html(view === 'table' ? this.buildTable() : this.buildTimeline())
        if (view === 'timeline') this.renderWeek(false)
    },

    selectWeek(idx) {
        if (idx < 0 || idx >= this.weeks.length || idx === this.selected) return
        const forward = idx > this.selected
        this.selected = idx
        this.renderWeek(forward ? 'right' : 'left')
    },

    // ---------- timeline ----------
    buildTimeline() {
        const chips = this.weeks
            .map(
                (w, i) =>
                    `<button type="button" class="tl-chip" data-week="${i}" title="${this.fmtDay(this.parseDay(w.start))} – ${this.fmtDay(this.parseDay(w.end))}">${w.week}</button>`
            )
            .join('')
        return `<nav class="tl-week-nav" tabindex="0" aria-label="Woche wählen">
                <button type="button" class="tl-step prev" aria-label="Vorherige Woche">${this.icon('chevron-left')}</button>
                <div class="tl-chips">${chips}</div>
                <button type="button" class="tl-step next" aria-label="Nächste Woche">${this.icon('chevron-right')}</button>
            </nav>
            <div class="tl-week"></div>`
    },

    renderWeek(direction) {
        const idx = this.selected
        const w = this.weeks[idx]
        this.root.find('.tl-chip').each((i, el) => {
            $(el)
                .toggleClass('selected', i === idx)
                .toggleClass('past', i < this.today)
                .toggleClass('today', i === this.today)
        })
        this.root
            .find('.tl-step.prev')
            .attr('data-week', idx - 1)
            .prop('disabled', idx === 0)
        this.root
            .find('.tl-step.next')
            .attr('data-week', idx + 1)
            .prop('disabled', idx === this.weeks.length - 1)

        const chip = this.root.find('.tl-chip.selected')[0]
        const strip = this.root.find('.tl-chips')[0]
        if (chip && strip)
            strip.scrollLeft = chip.offsetLeft - strip.clientWidth / 2 + chip.clientWidth / 2

        const start = this.parseDay(w.start),
            end = this.parseDay(w.end)
        const badge = idx === this.today ? '<span class="tl-badge">aktuelle Woche</span>' : ''
        const vacation = this.vacationRanges(w)
            .map((r) =>
                this.sameDay(r.start, r.end)
                    ? this.fmtDay(r.start)
                    : `${this.fmtDay(r.start)} – ${this.fmtDay(r.end)}`
            )
            .join(', ')
        const lectures = (w.content ?? []).map((l) => this.lectureCard(l)).join('')
        const events = (w.events ?? []).map((e) => this.eventItem(e)).join('')

        const week = this.root.find('.tl-week')
        week.removeClass('in-left in-right')
        week.html(`<section class="tl-week-head">
                <div class="tl-week-nr" aria-hidden="true">${this.pad(w.week)}</div>
                <div class="tl-week-title">
                    <div class="tl-kicker">// ${w.week}. Woche · KW ${this.isoWeek(start)} ${badge}</div>
                    <h2>${w.label ?? ''}</h2>
                    <div class="tl-range">${this.icon('calendar')} ${this.fmtDay(start)} – ${this.fmtDay(end)}</div>
                    ${vacation ? `<div class="tl-range tl-vacation">${this.icon('calendar-off')} vorlesungsfrei: ${vacation}</div>` : ''}
                </div>
            </section>
            ${lectures ? `<h3 class="tl-section">${this.icon('book-open')} Lerninhalte</h3><div class="tl-grid">${lectures}</div>` : ''}
            <h3 class="tl-section">${this.icon('list-checks')} Termine</h3>
            ${events ? `<ol class="tl-events">${events}</ol>` : '<p class="tl-empty">Keine Termine in dieser Woche.</p>'}`)
        if (direction) {
            // restart the slide-in animation
            void week[0].offsetWidth
            week.addClass(direction === 'right' ? 'in-right' : 'in-left')
        }
    },

    lectureCard(lecture) {
        const preview = this.previews[lecture.nr]
        const fallback = `<div class="tl-thumb-fallback">${lecture.nr ?? ''}</div>`
        const thumb = lecture.liveEmbed
            ? `<iframe loading="lazy" sandbox="allow-scripts allow-same-origin" src="${lecture.slides}?preview-slide#/${lecture.previewSlide ?? 0}" title="Vorschau"></iframe>`
            : `${preview?.startsWith('data:image/') ? `<img alt="" src="${preview}">` : ''}${fallback}`
        const thumbLink = lecture.slides
            ? `<a class="tl-thumb" href="${lecture.slides}" target="_blank" rel="noopener">${thumb}</a>`
            : `<div class="tl-thumb">${thumb}</div>`
        return `<article class="tl-card">
                <div class="tl-thumb-wrap">${thumbLink}<span class="tl-stamp">${this.pad(lecture.nr ?? 0)}</span></div>
                <div class="tl-card-body">
                    <h3>${lecture.title ?? ''}</h3>
                    <div class="tl-actions">${this.lectureActions(lecture)}</div>
                </div>
            </article>`
    },

    eventItem(e) {
        const date = e.date ? this.parseDay(e.date) : undefined
        const time = e.time ? `${e.timePrefix ? e.timePrefix + ' ' : ''}${e.time}` : ''
        const when = date
            ? `<div class="tl-cal"><span class="tl-cal-wd">${this.WEEKDAYS[date.getDay()].slice(0, 2)}</span><span class="tl-cal-d">${date.getDate()}</span><span class="tl-cal-m">${this.monthShort(date)}</span></div>${time ? `<span class="tl-tm">${time}</span>` : ''}`
            : ''
        const live = this.liveState(e)
        const content =
            e.content && e.content.trim() !== ''
                ? `<div class="tl-ev-text ${e.contentClass ?? ''}">${this.markup(e.content)}</div>`
                : ''
        const type = e.type ?? 'other'
        return `<li class="tl-ev type-${type} ${e.subtype ? 'sub-' + e.subtype : ''} ${date && this.sameDay(date, new Date()) ? 'is-today' : ''}">
                <div class="tl-when">${when}</div>
                <div class="tl-dot"></div>
                <div class="tl-ev-main">
                    <h4><span class="tl-ico">${this.mdiIcon(e.icon)}</span>${this.markup(e.title)}${live ? `<span class="tl-live">${live}</span>` : ''}</h4>
                    ${content}
                </div>
            </li>`
    },

    // LIVE during a lecture/question time today, DEMNÄCHST in the hour before
    liveState(e) {
        if (
            (e.type !== 'lecture' && e.type !== 'ask') ||
            !e.date ||
            !this.sameDay(this.parseDay(e.date), new Date())
        )
            return ''
        const start = this.minutesOf(e.time)
        if (start === undefined) return ''
        const now = new Date().getHours() * 60 + new Date().getMinutes()
        if (now >= start && now < start + 120) return 'LIVE'
        if (now >= start - 60 && now < start) return 'DEMNÄCHST'
        return ''
    },

    // ---------- lesson table ----------
    testSpans() {
        const all = this.weeks.flatMap((w) => w.events ?? [])
        const span = (e, type) => {
            const end = all.find((x) => x.nr === e.nr && x.type === type && x.subtype === 'end')
            const start = this.parseDay(e.date)
            return {
                type,
                start,
                end: end ? this.parseDay(end.date) : start,
                sortNumber: 2 * (e.nr - 1) + (type === 'prepare' ? 0 : 1),
                label: e.short ?? e.topic ?? '',
                title: e.topic ?? '',
                link: e.link,
            }
        }
        return ['prepare', 'homework']
            .flatMap((type) =>
                all
                    .filter((e) => e.type === type && e.subtype === 'begin')
                    .map((e) => span(e, type))
            )
            .sort((a, b) => a.sortNumber - b.sortNumber)
    },

    // packs the tests into lanes (table columns): a test goes into the first lane of its
    // type that is free on its start day, so a lane only ever holds tests of one type.
    // The homework lanes come first, then the prepare lanes
    testLanes(tests) {
        const byType = { prepare: [], homework: [] }
        const sorted = [...tests].sort((a, b) => a.start - b.start || a.sortNumber - b.sortNumber)
        for (const t of sorted) {
            const lanes = byType[t.type]
            let lane = lanes.find((l) => l.tests[l.tests.length - 1].end < t.start)
            if (!lane) lanes.push((lane = { type: t.type, tests: [] }))
            lane.tests.push(t)
        }
        return byType.homework.concat(byType.prepare)
    },

    buildTable() {
        const MAX = this.MAX_CONTENT_PER_DAY
        const all = this.weeks.flatMap((w) => w.events ?? [])
        const lanes = this.testLanes(this.testSpans())
        const finals = all.filter(
            (e) => (e.type === 'homework' && e.subtype === 'end') || e.type === 'lectureend'
        )
        const finalEvent = finals[finals.length - 1]
        const lectureEndEvent = all.find((e) => e.type === 'lectureend')

        const firstDay = this.parseDay(this.weeks[0].start)
        const lastDay = this.parseDay(
            finalEvent ? finalEvent.date : this.weeks[this.weeks.length - 1].end
        )
        const lectureEnd = lectureEndEvent ? this.parseDay(lectureEndEvent.date) : lastDay
        const todayIso = this.isoDay(new Date())

        const weekFor = (day) =>
            this.weeks.find(
                (w) => this.parseDay(w.start) <= day && day <= this.parseDay(w.end)
            ) ?? this.weeks[this.weeks.length - 1]

        // a weekday (Mon-Fri) without lectures: vacation, public holiday or after the lecture period
        const isFree = (w, day) =>
            (w.vacations ?? []).includes(this.isoDay(day)) || day > lectureEnd || this.isHoliday(day)
        // all weekdays of the calendar week of `day` are free
        const isFreeWeek = (day) => {
            const monday = this.addDays(day, -this.isoWeekday(day))
            const w = weekFor(monday)
            return [0, 1, 2, 3, 4].every((d) => isFree(w, this.addDays(monday, d)))
        }
        // a test is drawn as one cell per run of days that are (not) in a free week, so the
        // part running through e.g. the christmas break can look different (.paused)
        const segmentsOf = (t) => {
            const segments = []
            for (let day = t.start; day <= t.end; day = this.addDays(day, 1)) {
                const paused = isFreeWeek(day)
                const last = segments[segments.length - 1]
                if (last && last.paused === paused) last.end = day
                else segments.push({ start: day, end: day, paused })
            }
            // the label goes into the longest segment, preferably one that is not paused
            const days = (sg) => this.dayDiff(sg.start, sg.end) + (sg.paused ? 0 : 1000)
            segments.reduce((a, b) => (days(b) > days(a) ? b : a)).label = true
            return segments
        }
        lanes.forEach((lane) => lane.tests.forEach((t) => (t.segments = segmentsOf(t))))

        const rows = []
        for (let monday = firstDay; monday <= lastDay; monday = this.addDays(monday, 7)) {
            const w = weekFor(monday)
            const freeWeek = isFreeWeek(monday)
            for (let d = 0; d < 7; d++) {
                const day = this.addDays(monday, d)
                const iso = this.isoDay(day)
                const free = d <= 4 && isFree(w, day)
                const cls = [`d${d}`, d > 4 ? 'weekend' : '', iso === todayIso ? 'today' : ''].join(
                    ' '
                )
                const freeCls = free ? ' free' : ''

                let cells = ''
                if (d === 0)
                    cells += `<td class="week${freeWeek ? ' free-week' : ''}" rowspan="7"><b>${w.week}. Woche</b><span>KW ${this.isoWeek(day)}</span></td>`
                cells += `<td class="dow${freeCls}">${this.WEEKDAYS[day.getDay()].slice(0, 2)}</td><td class="day${freeCls}">${this.fmtShort(day)}</td>`

                const hasLecture = (w.events ?? []).some(
                    (e) => e.type === 'lecture' && e.date && this.sameDay(this.parseDay(e.date), day)
                )
                for (let i = 0; i < MAX; i++) {
                    const lecture = hasLecture ? (w.content ?? [])[i] : undefined
                    const edge = (i === 0 ? ' first' : '') + (i === MAX - 1 ? ' last' : '')
                    cells += `<td class="content${freeCls}${edge}">${lecture ? this.tableLecture(lecture) : ''}</td>`
                }

                lanes.forEach((lane, i) => {
                    const edge = i === 0 ? ' first' : ''
                    const t = lane.tests.find((t) => t.start <= day && day <= t.end)
                    if (!t) {
                        cells += `<td class="test ${lane.type}${edge}"></td>`
                    } else {
                        const k = t.segments.findIndex((sg) => this.sameDay(sg.start, day))
                        const sg = t.segments[k]
                        if (sg) {
                            const span = this.dayDiff(sg.start, sg.end) + 1
                            const segCls =
                                (sg.paused ? ' paused' : '') +
                                (k === 0 ? ' seg-first' : '') +
                                (k === t.segments.length - 1 ? ' seg-last' : '')
                            const label = t.link
                                ? `<a href="${t.link}" target="_blank" rel="noopener">${t.label}</a>`
                                : t.label
                            cells += `<td class="test ${t.type} selected${segCls}${edge}" rowspan="${span}" title="${t.title}: ${this.fmtDay(t.start)} – ${this.fmtDay(t.end)}">${sg.label ? `<div>${label}</div>` : ''}</td>`
                        }
                    }
                })
                cells += '<td class="spacer"></td>'
                rows.push(`<tr class="${cls}">${cells}</tr>`)
            }
        }

        const legend = `<div class="tl-legend">
            <span><i class="sw homework"></i>Frag-Uns-Aufgabe</span>
            <span><i class="sw prepare"></i>Boss-Level</span>
            <span><i class="sw free"></i>vorlesungsfrei / Feiertag</span>
        </div>`
        return `<div class="tl-table-wrap">
                <table class="tl-table">
                    <thead>
                        <tr><th>Woche</th><th colspan="2">Tag</th><th colspan="${MAX}">Stoff</th><th colspan="${lanes.length + 1}">Übungen</th></tr>
                        <tr class="tl-legend-row"><th colspan="${3 + MAX + lanes.length + 1}">${legend}</th></tr>
                    </thead>
                    <tbody>${rows.join('')}</tbody>
                </table>
            </div>`
    },

    tableLecture(lecture) {
        const title = lecture.slides
            ? `<a href="${lecture.slides}" target="_blank" rel="noopener">${lecture.title}</a>`
            : lecture.title
        return `<div class="tl-tl-title">${title}</div><div class="tl-tl-links">${this.lectureActions(lecture)}</div>`
    },

    // ---------- style ----------
    css() {
        return `
.gdi-tl {
    --coral: #ff6b6b; --brand: #ec5f3d; --brand-deep: #c2410c; --brand-soft: #fff1ec;
    --ink: #1c1917; --muted: #78716c; --line: #ece7e3; --surface: #ffffff; --surface-2: #faf7f5;
    --prepare: #5b6ee1; --prepare-soft: #eef0fc; --homework: #f08a5d; --homework-soft: #fef0e8;
    --lecture: #a43fc0; --lecture-soft: #f7ebfa; --recording: #e0a800; --free: #fff6cc;
    --display: "Avenir Next", "Segoe UI Variable Display", "Segoe UI", system-ui, sans-serif;
    --mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
    --radius: 14px;
    font: 14px/1.5 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
    color: var(--ink); background: var(--surface-2); border-radius: 10px; overflow: hidden;
    /* own stacking context: the host page's z-index rules must not reorder the layers */
    position: relative; isolation: isolate; text-align: left; hyphens: manual;
}
.gdi-tl *, .gdi-tl *::before, .gdi-tl *::after { box-sizing: border-box; }
.gdi-tl a { color: var(--brand); text-decoration: none; }
.gdi-tl a:hover { text-decoration: underline; text-underline-offset: 2px; }
.gdi-tl button { font: inherit; cursor: pointer; }
.gdi-tl .tl-icon { flex: none; width: 1em; height: 1em; vertical-align: -.125em; }

/* ---------- hero ---------- */
.tl-hero {
    position: relative; z-index: 1; color: #fff; padding: 22px 24px 18px;
    background:
        radial-gradient(circle at 92% -20%, rgba(255,255,255,.28), transparent 45%),
        linear-gradient(rgba(255,255,255,.07) 1px, transparent 1px) 0 0 / 22px 22px,
        linear-gradient(90deg, rgba(255,255,255,.07) 1px, transparent 1px) 0 0 / 22px 22px,
        linear-gradient(120deg, var(--coral), var(--brand) 55%, var(--brand-deep));
}
.tl-hero-top { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; }
.tl-hero-kicker { font: 600 12px/1 var(--mono); letter-spacing: .08em; text-transform: uppercase; opacity: .85; }
.tl-hero h1 { margin: 6px 0 0; font: 700 26px/1.1 var(--display); letter-spacing: -.01em; color: #fff; }
.tl-tabs { display: inline-flex; gap: 2px; background: rgba(0,0,0,.16); border-radius: 999px; padding: 4px; backdrop-filter: blur(4px); }
.tl-tabs button { display: inline-flex; align-items: center; gap: 6px; border: 0; background: transparent; color: rgba(255,255,255,.88); padding: 7px 16px; border-radius: 999px; font-weight: 600; transition: background .2s, color .2s; }
.tl-tabs button:hover { color: #fff; background: rgba(255,255,255,.12); }
.tl-tabs button.active { background: #fff; color: var(--brand); box-shadow: 0 2px 8px rgba(0,0,0,.15); }
.tl-progress { display: flex; align-items: center; gap: 12px; margin-top: 18px; font: 600 12px/1 var(--mono); }
.tl-progress-track { flex: 1; height: 6px; border-radius: 999px; background: rgba(255,255,255,.25); overflow: hidden; }
.tl-progress-fill { height: 100%; border-radius: inherit; background: #fff; box-shadow: 0 0 12px rgba(255,255,255,.8); }
.tl-hero.has-links { padding-bottom: 34px; }
/* the stickers overlap the hero; fixed layer order, whatever the host page sets on divs */
.gdi-tl > .tl-hero { z-index: 1 !important; }
.gdi-tl > .tl-links { z-index: 3 !important; }
.gdi-tl > .tl-body { position: relative; z-index: 2 !important; }
.tl-body { padding: 20px 24px 24px; }

/* ---------- quick links: crooked stickers that straighten up on hover ---------- */
.tl-links { position: relative; z-index: 3; display: flex; flex-wrap: wrap; justify-content: flex-start; gap: 18px 14px; margin-top: -18px; padding: 0 24px 6px; }
.tl-link { --bg: var(--brand); --fg: #fff; position: relative; flex: 1 1 170px; max-width: 250px; display: flex; flex-direction: column; gap: 4px; padding: 12px 14px 11px; border-radius: 10px; background: var(--bg); color: var(--fg) !important; border: 2px solid var(--ink); box-shadow: 4px 4px 0 var(--ink); text-decoration: none !important; transform: translateY(var(--shift)) rotate(var(--tilt)); transition: transform .25s cubic-bezier(.3,1.6,.5,1), box-shadow .2s; }
.tl-link:nth-child(even) { border-radius: 14px 6px 12px 8px; }
.tl-link:nth-child(3n) { border-radius: 6px 14px 8px 12px; }
.tl-link:hover, .tl-link:focus-visible { transform: translateY(-3px) rotate(0) scale(1.03); box-shadow: 7px 7px 0 var(--ink); outline: none; z-index: 1; }
.tl-link:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 var(--ink); }
/* a strip of tape holding the sticker */
.tl-link::before { content: ""; position: absolute; top: -10px; left: 50%; width: 46px; height: 16px; background: rgba(255,255,255,.6); box-shadow: 0 1px 2px rgba(0,0,0,.18); transform: translateX(-50%) rotate(calc(var(--tilt) * -2.5)); }
.tl-link.c-yellow { --bg: #f2c037; --fg: var(--ink); }
.tl-link.c-purple { --bg: #9c27b0; }
.tl-link.c-blue { --bg: #1976d2; }
.tl-link.c-coral { --bg: var(--coral); }
.tl-link.c-green { --bg: #2e9d6a; }
.tl-link-title { display: flex; align-items: center; gap: 8px; font: 800 19px/1.1 var(--display); letter-spacing: -.01em; }
.tl-link-desc { text-align: left; font-size: 12.5px; line-height: 1.35; opacity: .85; }
.tl-link-desc b { font-weight: 700; }
@media (prefers-reduced-motion: reduce) { .tl-link { transition: none; } }

/* ---------- week track ---------- */
.tl-week-nav { display: flex; align-items: center; gap: 8px; margin-bottom: 36px; outline: none; }
.tl-week-nav:focus-visible { box-shadow: 0 0 0 2px var(--brand); border-radius: 10px; }
.tl-step { flex: none; width: 36px; height: 36px; border-radius: 50%; border: 1px solid var(--line); background: var(--surface); color: var(--ink); font-size: 18px; display: grid; place-items: center; transition: all .15s; }
.tl-step:hover:not(:disabled) { background: var(--brand); border-color: var(--brand); color: #fff; }
.tl-step:disabled { opacity: .3; cursor: default; }
.tl-chips { position: relative; display: flex; gap: 10px; overflow-x: auto; scroll-behavior: smooth; scrollbar-width: none; flex: 1;
    /* room for the glow of the selected chip, which the scroll container would clip */
    padding: 20px 14px; margin: -14px -8px;
    /* fade chips out towards the step buttons instead of cutting them off at the scroll edge */
    -webkit-mask-image: linear-gradient(90deg, transparent, #000 14px, #000 calc(100% - 14px), transparent);
    mask-image: linear-gradient(90deg, transparent, #000 14px, #000 calc(100% - 14px), transparent); }
.tl-chips::-webkit-scrollbar { display: none; }
.tl-chips::before { content: ""; position: absolute; left: 0; right: 0; top: 50%; height: 2px; background: var(--line); min-width: 100%; }
.tl-chip { position: relative; flex: none; width: 34px; height: 34px; border-radius: 50%; border: 2px solid var(--line); background: var(--surface); color: var(--muted); font: 700 13px/1 var(--mono); transition: transform .15s, background .15s; }
.tl-chip:hover { transform: scale(1.1); border-color: var(--coral); color: var(--brand); }
.tl-chip.past { background: var(--brand-soft); border-color: #f6c8b8; color: var(--brand); }
.tl-chip.today { border-color: var(--brand); color: var(--brand); box-shadow: 0 0 0 4px rgba(236,95,61,.18); }
.tl-chip.selected { background: var(--brand); border-color: var(--brand); color: #fff; transform: scale(1.12); box-shadow: 0 4px 12px rgba(236,95,61,.4); }

.tl-week.in-right { animation: tl-in-right .3s cubic-bezier(.2,.8,.2,1); }
.tl-week.in-left { animation: tl-in-left .3s cubic-bezier(.2,.8,.2,1); }
@keyframes tl-in-right { from { opacity: 0; transform: translateX(28px); } }
@keyframes tl-in-left { from { opacity: 0; transform: translateX(-28px); } }

/* ---------- week head ---------- */
.tl-week-head { display: flex; align-items: center; gap: 18px; margin-bottom: 8px; }
.tl-week-nr { font: 800 76px/.85 var(--display); letter-spacing: -.04em; color: transparent; -webkit-text-stroke: 2px var(--coral); background: linear-gradient(180deg, transparent 55%, var(--brand-soft) 55%); -webkit-background-clip: text; background-clip: text; }
.tl-week-title h2 { margin: 2px 0 4px; font: 700 24px/1.15 var(--display); color: var(--ink); }
.tl-kicker { font: 600 12px/1.4 var(--mono); color: var(--brand); }
.tl-badge { margin-left: 6px; padding: 2px 8px; border-radius: 999px; background: var(--brand); color: #fff; font: 600 11px/1 system-ui, sans-serif; vertical-align: 1px; display: inline-block; white-space: nowrap; }
.tl-range { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); font-size: 13px; }
.tl-vacation { display: flex; margin-top: 4px; }
.tl-section { display: flex; align-items: center; gap: 8px; margin: 22px 0 12px; font: 700 12px/1 var(--mono); text-transform: uppercase; letter-spacing: .1em; color: var(--muted); }
.tl-section::after { content: ""; flex: 1; height: 1px; background: var(--line); }

/* ---------- lecture cards ---------- */
.tl-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; }
.tl-card { position: relative; background: var(--surface); border-radius: var(--radius); overflow: hidden; display: flex; flex-direction: column; box-shadow: 0 1px 2px rgba(28,25,23,.06), 0 0 0 1px var(--line); transition: box-shadow .25s, transform .25s; }
.tl-card::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; background: linear-gradient(90deg, var(--coral), var(--brand)); transform: scaleX(0); transform-origin: left; transition: transform .3s; }
.tl-card:hover { transform: translateY(-3px); box-shadow: 0 14px 30px -10px rgba(194,65,12,.35), 0 0 0 1px #f6c8b8; }
.tl-card:hover::after { transform: scaleX(1); }
.tl-thumb-wrap { position: relative; }
.tl-thumb { position: relative; display: block; aspect-ratio: 4 / 3; overflow: hidden; background: repeating-linear-gradient(45deg, var(--brand-soft) 0 10px, #fff7f3 10px 20px); }
.tl-thumb img, .tl-thumb iframe { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; border: 0; z-index: 1; transition: transform .4s; }
.tl-card:hover .tl-thumb img { transform: scale(1.04); }
.tl-thumb iframe { pointer-events: none; }
.tl-thumb-fallback { position: absolute; inset: 0; z-index: 0 !important; display: grid; place-items: center; font: 800 48px/1 var(--display); color: #f6c8b8; }
.tl-stamp { position: absolute; z-index: 2; left: 10px; bottom: -14px; min-width: 34px; height: 28px; padding: 0 8px; border-radius: 8px; display: grid; place-items: center; background: var(--ink); color: #fff; font: 700 13px/1 var(--mono); box-shadow: 0 4px 10px rgba(0,0,0,.25); }
.tl-card-body { padding: 20px 12px 8px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.tl-card h3 { margin: 0; font: 650 15px/1.3 var(--display); color: var(--ink); }
.tl-actions { display: flex; gap: 2px; margin-top: auto; padding-top: 4px; border-top: 1px dashed var(--line); }
.tl-action { display: inline-grid; place-items: center; width: 32px; height: 32px; border-radius: 9px; color: var(--muted) !important; font-size: 18px; text-decoration: none !important; transition: background .15s, color .15s; }
.tl-action:hover { background: var(--brand-soft); color: var(--brand) !important; }
.tl-action.accent { color: var(--brand) !important; margin-left: auto; }

/* ---------- events ---------- */
.tl-events { list-style: none; margin: 0; padding: 0; }
.tl-ev { --c: var(--muted); --c-soft: var(--surface); display: grid; grid-template-columns: 58px 22px 1fr; column-gap: 10px; }
.tl-ev.type-lecture { --c: var(--lecture); --c-soft: var(--lecture-soft); }
.tl-ev.type-homework { --c: var(--homework); --c-soft: var(--homework-soft); }
.tl-ev.type-prepare { --c: var(--prepare); --c-soft: var(--prepare-soft); }
.tl-ev.type-lectureend, .tl-ev.type-signupend, .tl-ev.type-tutorialstart { --c: var(--brand); --c-soft: var(--brand-soft); }
.tl-ev.type-exam { --c: var(--brand-deep); --c-soft: var(--brand-soft); }
.tl-when { display: flex; flex-direction: column; align-items: center; gap: 4px; padding-bottom: 14px; }
.tl-cal { width: 52px; border-radius: 10px; overflow: hidden; background: var(--surface); text-align: center; box-shadow: 0 1px 2px rgba(0,0,0,.06), 0 0 0 1px var(--line); }
.tl-cal-wd { display: block; background: var(--c); color: #fff; font: 700 10px/1 var(--mono); text-transform: uppercase; letter-spacing: .08em; padding: 4px 0 3px; }
.tl-cal-d { display: block; font: 800 20px/1.1 var(--display); padding-top: 3px; color: var(--ink); }
.tl-cal-m { display: block; font: 600 10px/1 var(--mono); text-transform: uppercase; color: var(--muted); padding-bottom: 5px; }
.tl-tm { font: 600 10px/1.2 var(--mono); color: var(--muted); text-align: center; white-space: nowrap; }
.tl-dot { position: relative; display: flex; justify-content: center; }
.tl-dot::before { content: ""; position: relative; z-index: 1; margin-top: 22px; width: 12px; height: 12px; border-radius: 50%; background: var(--surface-2); border: 3px solid var(--c); }
.tl-dot::after { content: ""; position: absolute; top: 0; bottom: 0; width: 2px; background: var(--line); }
.tl-ev:first-child .tl-dot::after { top: 22px; }
.tl-ev:last-child .tl-dot::after { bottom: auto; height: 22px; }
.tl-ev.is-today .tl-dot::before { background: var(--c); box-shadow: 0 0 0 5px var(--c-soft); }
/* deadline of a homework ("Aufgabe - Bearbeitungsende"): the dot blinks and sends out a pulsing ring */
.tl-ev.type-homework.sub-end .tl-dot::before { animation: tl-blink 1.1s ease-in-out infinite; }
@keyframes tl-blink {
    0%, 100% { background: var(--c); transform: scale(1); box-shadow: 0 0 0 0 rgba(240, 138, 93, .6); }
    50% { background: var(--surface); transform: scale(1.35); box-shadow: 0 0 0 9px rgba(240, 138, 93, 0); }
}
@media (prefers-reduced-motion: reduce) { .tl-ev.type-homework.sub-end .tl-dot::before { animation: none; background: var(--c); } }
.tl-ev-main { align-self: start; margin-bottom: 14px; padding: 12px 14px; border-radius: 12px; background: var(--surface); border-left: 4px solid var(--c); box-shadow: 0 1px 2px rgba(0,0,0,.05), 0 0 0 1px var(--line); min-width: 0; }
.tl-ev-main h4 { margin: 0; font: 650 15px/1.35 var(--display); color: var(--ink); display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.tl-ico { display: inline-grid; place-items: center; width: 28px; height: 28px; border-radius: 8px; background: var(--c-soft); color: var(--c); font-size: 16px; }
.tl-ev-text { margin-top: 6px; color: #57534e; }
.tl-ev-text.temp { display: none; }
.tl-ev-text p { margin: 0 0 6px; }
.tl-ev-main .stream, .tl-ev-main .recording { display: inline-flex; align-items: center; gap: 4px; padding: 3px 10px; border-radius: 999px; color: #fff !important; font-size: 13px; text-decoration: none !important; transition: filter .15s, transform .15s; }
.tl-ev-main .stream { background: var(--lecture); }
.tl-ev-main .recording { background: var(--recording); }
.tl-ev-main .stream:hover, .tl-ev-main .recording:hover { filter: brightness(1.1); transform: translateY(-1px); }
.tl-inline-icon { display: inline-flex; font-size: 15px; }
.tl-live { padding: 2px 8px; border-radius: 999px; background: #dc2626; color: #fff; font: 700 11px/1.3 var(--mono); letter-spacing: .06em; animation: tl-pulse 1.6s infinite; }
@keyframes tl-pulse { 50% { opacity: .55; } }
.gdi-tl hl { display: inline-block; border: 1px dashed #f2c037; padding: 1px 4px; border-radius: 4px; }
.gdi-tl c, .gdi-tl code { font: 12px var(--mono); background: var(--brand-soft); color: var(--brand-deep); border-radius: 4px; padding: 1px 5px; }
.tl-empty { color: var(--muted); font-style: italic; }

/* ---------- lesson table ---------- */
.tl-legend { display: flex; gap: 18px; flex-wrap: wrap; font: 500 12px/1.2 system-ui, sans-serif; color: var(--muted); text-transform: none; letter-spacing: normal; }
.tl-legend span { display: inline-flex; align-items: center; gap: 6px; }
.tl-legend .sw { width: 14px; height: 14px; border-radius: 4px; display: inline-block; }
.sw.prepare { background: var(--prepare); } .sw.homework { background: var(--homework); } .sw.free { background: var(--free); box-shadow: inset 0 0 0 1px #ecd97a; }
.tl-table-wrap { margin-top: 18px; max-height: 640px; overflow: auto; border-radius: var(--radius); background: var(--surface); box-shadow: 0 0 0 1px var(--line); }
.tl-table { border-collapse: separate; border-spacing: 0; width: 100%; font-size: 12px; }
.tl-table th { position: sticky; top: 0; z-index: 3; background: var(--ink); color: #fff; text-align: left; padding: 9px 8px; font: 700 11px/1 var(--mono); text-transform: uppercase; letter-spacing: .08em; }
.tl-table td { padding: 3px 6px; border-bottom: 1px solid #f3efec; vertical-align: top; }
.tl-table tr.d0 td { border-top: 2px solid var(--line); }
.tl-table tr.weekend td:not(.week):not(.test) { background: var(--surface-2); color: #b8b0aa; }
.tl-table tr.today td.dow, .tl-table tr.today td.day { background: var(--brand); color: #fff; font-weight: 700; }
/* week and day stay in place while the table scrolls sideways (fixed widths for the left offsets) */
/* starts where the week name in the column below starts (4px bar + 10px padding) */
.tl-table th:nth-child(1) { position: sticky; left: 0; z-index: 4; padding-left: 14px; }
.tl-table th:nth-child(2) { position: sticky; left: 92px; z-index: 4; }
/* the legend sits in a second header row, sticky right below the first one (9px + 11px + 9px) */
.tl-table tr.tl-legend-row th { top: 29px; left: auto; z-index: 3; padding: 2px 8px 9px 14px; }
.tl-table tr.tl-legend-row .tl-legend { color: rgba(255, 255, 255, .75); }
.tl-table td.week { position: sticky; left: 0; z-index: 2; width: 92px; min-width: 92px; max-width: 92px; background: var(--surface); border-right: 1px solid var(--line); border-left: 4px solid var(--coral); white-space: nowrap; padding: 8px 10px; }
/* a week without any lecture day gets the yellow of the link cards instead of the red bar */
.tl-table td.week.free-week { border-left-color: #f2c037; }
.tl-table td.week b { font: 700 13px/1.2 var(--display); }
.tl-table td.week span { display: block; color: var(--muted); font: 11px var(--mono); }
.tl-table td.dow { position: sticky; left: 92px; z-index: 2; width: 30px; min-width: 30px; max-width: 30px; background: var(--surface); color: var(--muted); font-family: var(--mono); }
.tl-table td.day { position: sticky; left: 122px; z-index: 2; width: 72px; min-width: 72px; max-width: 72px; background: var(--surface); font-family: var(--mono); border-right: 1px solid var(--line); }
.tl-table td.free { background: var(--free) !important; color: #a8952f !important; }
.tl-table td.content { min-width: 110px; }
.tl-table td.content.last { border-right: 1px solid var(--line); }
.tl-tl-title { font-weight: 650; line-height: 1.25; }
.tl-tl-links .tl-action { width: 22px; height: 22px; font-size: 14px; border-radius: 6px; }
/* the exercise columns: a gap between neighbouring columns, continuous bars inside a column */
.tl-table td.test { width: 24px; min-width: 24px; padding: 0; border-bottom: 0; border-left: 2px solid var(--surface); border-right: 1px solid var(--surface); background-clip: padding-box; background-image: linear-gradient(90deg, transparent calc(50% - .5px), #f1ece8 calc(50% - .5px), #f1ece8 calc(50% + .5px), transparent calc(50% + .5px)); }
.tl-table tr.d0 td.test { border-top: 0; }
/* empty last column, keeps the lanes clear of the (overlay) scrollbar */
.tl-table td.spacer { width: 16px; min-width: 16px; padding: 0; border: 0 !important; background: var(--surface) !important; }
.tl-table td.test.selected { background-image: none; position: relative; }
.tl-table td.test.selected.seg-first { border-top-left-radius: 8px; border-top-right-radius: 8px; }
.tl-table td.test.selected.seg-last { border-bottom-left-radius: 8px; border-bottom-right-radius: 8px; }
/* the part of a test in a week without lectures is striped (clear / half transparent) */
.tl-table td.test.prepare.selected.paused { background-color: transparent; background-image: repeating-linear-gradient(135deg, transparent 0 5px, color-mix(in srgb, var(--prepare) 50%, transparent) 5px 10px); }
.tl-table td.test.homework.selected.paused { background-color: transparent; background-image: repeating-linear-gradient(135deg, transparent 0 5px, color-mix(in srgb, var(--homework) 50%, transparent) 5px 10px); }
.tl-table td.test.prepare.selected { background-color: var(--prepare); }
.tl-table td.test.homework.selected { background-color: var(--homework); }
.tl-table td.test.selected:hover { filter: brightness(1.08); }
.tl-table td.test.selected div { writing-mode: vertical-lr; white-space: nowrap; margin: 8px auto; font: 600 11px/1 system-ui, sans-serif; color: #fff;
    /* the rotated glyphs sit on the baseline (left) side of the line box, so it looks off-center */
    transform: translateX(1px); }
.tl-table td.test.selected a { color: #fff; }

@media (max-width: 560px) {
    .tl-hero, .tl-body, .tl-links { padding-left: 14px; padding-right: 14px; }
    .tl-link { flex-basis: 140px; padding: 9px 11px 8px; }
    .tl-link-title { gap: 6px; font-size: 16px; }
    .tl-link-desc { font-size: 11.5px; }
    /* long titles wrap next to the icon instead of moving below it */
    .tl-ev-main h4 { display: block; }
    .tl-ev-main h4 .tl-ico { vertical-align: middle; margin-right: 6px; }
    .tl-hero h1 { font-size: 21px; }
    .tl-week-nr { font-size: 54px; }
    .tl-ev { grid-template-columns: 52px 16px 1fr; column-gap: 6px; }
    .tl-cal { width: 48px; }
    .tl-grid { grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 12px; }
}
`
    },
}
